export async function validateLicenseKey(input: ValidateLicenseKeyInput): Promise<ValidateLicenseKeyOutput> {
  return validateLicenseKeyFlow(input);
}

const db = getFirestore(app);

const validateLicenseKeyFlow = defineFlowOnce(
  {
    name: 'validateLicenseKeyFlow',
    inputSchema: ValidateLicenseKeyInputSchema,
    outputSchema: ValidateLicenseKeyOutputSchema,
  },
  async ({ licenseKey, userId }): Promise<ValidateLicenseKeyOutput> => {
    try {
      if (!licenseKey || !licenseKey.trim()) {
        return { success: false, error: "License key cannot be empty." };
      }
      if (!userId) {
        return { success: false, error: "User ID is required to claim a key." };
      }
      
      const key = licenseKey.trim();

      // Parse the multi-line string keys into arrays of valid keys
      const PRO_KEYS = PRO_KEYS_TEXT.split(/\s+/).filter(k => k);
      const STANDARD_KEYS = STANDARD_KEYS_TEXT.split(/\s+/).filter(k => k);

      // Step 1: Check if the key exists in either of the master lists.
      const isProKey = PRO_KEYS.includes(key);
      const isStandardKey = STANDARD_KEYS.includes(key);

      if (!isProKey && !isStandardKey) {
          return { success: false, error: "The license key is invalid or does not exist." };
      }
      
      const planId = isProKey ? 'pro' : 'standard';

      // Step 2: Check if the key has already been claimed.
      const claimedKeyRef = doc(db, "claimedKeys", key);
      const claimedKeySnap = await getDoc(claimedKeyRef);

      if (claimedKeySnap.exists()) {
        return { success: false, error: "This license key has already been claimed." };
      }
      
      // Step 3: Mark the key as claimed to prevent re-use.
      await setDoc(claimedKeyRef, {
        userId: userId,
        claimedAt: serverTimestamp(),
        planId: planId
      });

      return { success: true, planId };

    } catch (error: any) {
      console.error('Error in validateLicenseKeyFlow:', error);
      return {
        success: false,
        error: "An internal error occurred while validating the key. Please contact support.",
      };
    }
  }
);
